#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
layout(color) uniform half4 amzp_color1;
uniform float amzp_progressa;
uniform float amzp_ktime;
uniform float amzp_klength;
uniform float amzp_kalpha;
uniform float amzp_knum;
uniform float amzp_scale;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_bright;
uniform float amzp_alpha;
uniform float amzp_angle;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
    float hash(float x)
    {
       return fract(21654.6512 * sin(385.51 * x));
    }
    float hash( in float2 p )
    {
        return fract(sin(p.x*15.32+p.y*35.78) * 43758.23);
    }
    float2 hash2(float2 p)
    {
       return float2(hash(p*.754),hash(1.5743*p.yx+4.5891))-.5;
    }
    float2 hash2b(float2 p)
    {
       return float2(hash(p*.754),hash(1.5743*p+4.5476351));
    }
    float2 add = float2(1.0, 0.0);
    float2 noise2(float2 x)
    {
        float2 p = floor(x);
        float2 f = fract(x);
        f = f*f*(3.0-2.0*f);
        float2 res = mix(mix( hash2(p), hash2(p + add.xy),f.x),
                        mix( hash2(p + add.yx), hash2(p + add.xx),f.x),f.y);
        return res;
    }
    float2 fbm2(float2 x)
    {
        float2 r = float2(0.0);
        float a = 1.0;
        for (int i = 0; i < 8; i++)
        {
            r += abs(noise2(x)+.5 )* a;
            x *= 2.;
            a *= .5;
        }
        return r;
    }
    float2x2 m2;
    float2 fbm3(float2 x)
    {
        float2 r = float2(0.0);
        float a = 1.;
        for (int i = 0; i < 6; i++)
        {
            r += m2*noise2((x+r)/a)*a;
            r=-.8*abs(r);
            a*=1.7;
        }
        return r;
    }
    float3 storm(float2 x)
    {
        float t = .5*amzp_progressa;
        float st = sin(t), ct = cos(t);
        m2 = float2x2(ct,st,-st,ct);
        x=fbm3(x+0.5*amzp_progressa)+2.;
        x*=.35;
        float c = length(x);
        c=c*c*c;
        float3 col=float3(0.6-.1*x.x,0.7,0.8-.1*x.y)*c*x.y;
        return clamp(col,0.,1.);
    }
    float dseg( float2 ba, float2 pa )
    {
       float h = clamp( dot(pa,ba)/dot(ba,ba), -0.2, 1. );
       return length( pa - ba*h );
    }
    float arc(float2 x,float2 p, float2 dir)
    {
        float2 r = p;
        float d=10.;
        for (int i = 0; i < 5; i++)
        {
            float2 s= noise2(r+amzp_progressa)+dir;
            d=min(d,dseg(s,x-r));
            r +=s;
        }
        return d*3.;
    }
    float thunderbolt(float2 x,float2 tgt)
    {
        float2 r = tgt;
        float d=1000.;
        float dist=length(tgt-x);
        for (int i = 0; i < 11; i++)
        {
            if(r.y>x.y+.5)break;
            float2 s= (noise2(r+amzp_progressa)+float2(0.,.7))*2.;
            dist = dseg(s * amzp_klength,x-r);
            d=min(d,dist);
            r +=s;
            if(i-(i/5)*5==0){
                if(i-(i/10)*10==0)d=min(d,arc(x,r,float2(.3,.5)));
                else d=min(d,arc(x,r,float2(-.3,.5)));
            }
        }
        return exp(-5.*d)+.2*exp(-1.*dist) ;
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((-225.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
       float2 p = satriyaid;
        float2 d;
        float2 tgt = float2(1., -8.);
        float c=0.;
        float3 col = float3(0.0);
         float t = hash(floor(5.*amzp_progressa * amzp_ktime));
        if(hash(t+2.3) > .8 )
        {
            for(float i = 1.0 ; i <= amzp_knum; i++){
                tgt+=8.*hash2b(tgt+t);
                c= thunderbolt(p*10.+2.*fbm2(5.*p),tgt);
                col+=clamp(1.7* amzp_color1.rgb *c,0.,1.);
            }
        }
       fragColor = float4(col * amzp_kalpha, 0.0);
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (newLayer(texColor, factor) * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

